import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.MobEffect{EntityRuntimeID: 300, Operation: packet.MobEffectAdd, EffectType: packet.EffectPoison,
#     Amplifier: 2, Particles: true, Duration: 600, Tick: 128, Ambient: false}
ADD = bytes.fromhex("ac0201260401b009800100")

# generated by gophertunnel b8bd735:
# &packet.MobEffect{EntityRuntimeID: 1, Operation: packet.MobEffectRemove, EffectType: packet.EffectSpeed,
#     Amplifier: -1, Particles: false, Duration: -1, Tick: 0, Ambient: true}
REMOVE_INFINITE = bytes.fromhex("0103020100010001")

# generated by gophertunnel b8bd735:
# &packet.MobEffect{EntityRuntimeID: 300, Operation: packet.MobEffectModify, Tick: 300}
UPDATE = bytes.fromhex("ac020200000000ac0200")

GOLDENS = [
    pytest.param(
        v2225.MobEffectPacket(
            runtime_id=300,
            event_id=v2225.MobEffectPacket.Event.ADD,
            effect_id=19,
            effect_amplifier=2,
            show_particles=True,
            effect_duration_ticks=600,
            tick=128,
            ambient=False,
        ),
        ADD,
        id="add",
    ),
    pytest.param(
        v2225.MobEffectPacket(
            runtime_id=1,
            event_id=v2225.MobEffectPacket.Event.REMOVE,
            effect_id=1,
            effect_amplifier=-1,
            show_particles=False,
            effect_duration_ticks=-1,
            tick=0,
            ambient=True,
        ),
        REMOVE_INFINITE,
        id="remove-infinite",
    ),
    pytest.param(
        v2225.MobEffectPacket(runtime_id=300, event_id=v2225.MobEffectPacket.Event.UPDATE, tick=300),
        UPDATE,
        id="update-multibyte-ids",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_mob_effect_is_packet_28(version):
    assert version.PACKETS[28] is version.MobEffectPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_mob_effect_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_mob_effect_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
